"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[7810],{14391:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"EnemyChrono","desc":"Registers each spawned NPC as a Chrono `ENEMY` entity (NATIVE mode) so\\nclients interpolate it with Chrono\'s buffer and the server keeps snapshot\\nhistory for LagCompensation. One Janitor per NPC.\\n\\nLifecycle: Humanoid.Died pauses replication (clients stop forcing the\\nCFrame, so the body falls with normal physics). The entity is destroyed\\nonly after the model leaves the DataModel \u2014 server `Entity.Destroy`\\ndestroys the model, so it must never run on a model still in the world.","realm":["Server"],"source":{"line":15,"path":"src/ServerStorage/SharedModules/EnemyChrono.luau"}}')}}]);